CREATE TABLE users(id INT PRIMARY KEY, name VARCHAR(16), age INT, city VARCHAR(16));
CREATE TABLE products(id INT PRIMARY KEY, title VARCHAR(32), price DOUBLE, stock INT);
CREATE TABLE orders(id INT PRIMARY KEY, user_id INT, product_id INT, amount DOUBLE, status VARCHAR(8));
CREATE TABLE events(tag VARCHAR(8), val INT);
CREATE INDEX idx_users_age ON users(age);
CREATE INDEX idx_orders_user ON orders(user_id);
CREATE INDEX idx_orders_status ON orders(status);
